arguments.command:
python3 -c "
from pptx import Presentation
prs = Presentation('/app/output/final_deck.pptx')
print(f'Slides: {len(prs.slides)}')
print(f'Width: {prs.slide_width}, Height: {prs.slide_height}')
for i, slide in enumerate(prs.slides):
    texts = []
    for shape in slide.shapes:
        if shape.has_text_frame:
            for p in shape.text_frame.paragraphs:
                if p.text.strip():
                    texts.append(p.text.strip()[:80])
                    break
        if shape.has_table:
            texts.append(f'[TABLE {shape.table.rows.__len__()}x{len(shape.table.columns)}]')
        if shape.has_chart:
            texts.append(f'[CHART: {shape.chart.chart_type}]')
    print(f'Slide {i+1}: {texts[0] if texts else \"empty\"} | shapes={len(slide.shapes)} | has_chart={any(s.has_chart for s in slide.shapes)} | has_table={any(s.has_table for s in slide.shapes)}')
"

